25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream XGMII frame transmitter (AXI in, XGMII out)
33	 */
34	module axis_xgmii_tx_64 #
35	(
36	    parameter DATA_WIDTH = 64,
37	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
38	    parameter CTRL_WIDTH = (DATA_WIDTH/8),
39	    parameter ENABLE_PADDING = 1,
40	    parameter ENABLE_DIC = 1,
41	    parameter MIN_FRAME_LENGTH = 64,
42	    parameter PTP_TS_ENABLE = 0,
43	    parameter PTP_TS_FMT_TOD = 1,
44	    parameter PTP_TS_WIDTH = PTP_TS_FMT_TOD ? 96 : 64,
45	    parameter PTP_TS_CTRL_IN_TUSER = 0,
46	    parameter PTP_TAG_ENABLE = PTP_TS_ENABLE,
47	    parameter PTP_TAG_WIDTH = 16,
48	    parameter USER_WIDTH = (PTP_TS_ENABLE ? (PTP_TAG_ENABLE ? PTP_TAG_WIDTH : 0) + (PTP_TS_CTRL_IN_TUSER ? 1 : 0) : 0) + 1
49	)
50	(
51	    input  wire                      clk,
52	    input  wire                      rst,
53	
54	    /*
55	     * AXI input
56	     */
57	    input  wire [DATA_WIDTH-1:0]     s_axis_tdata,
58	    input  wire [KEEP_WIDTH-1:0]     s_axis_tkeep,
59	    input  wire                      s_axis_tvalid,
60	    output wire                      s_axis_tready,
61	    input  wire                      s_axis_tlast,
62	    input  wire [USER_WIDTH-1:0]     s_axis_tuser,
63	
64	    /*
65	     * XGMII output
66	     */
67	    output wire [DATA_WIDTH-1:0]     xgmii_txd,
68	    output wire [CTRL_WIDTH-1:0]     xgmii_txc,
69	
70	    /*
71	     * PTP
72	     */
73	    input  wire [PTP_TS_WIDTH-1:0]   ptp_ts,
74	    output wire [PTP_TS_WIDTH-1:0]   m_axis_ptp_ts,
75	    output wire [PTP_TAG_WIDTH-1:0]  m_axis_ptp_ts_tag,
76	    output wire                      m_axis_ptp_ts_valid,
77	
78	    /*
79	     * Configuration
80	     */
81	    input  wire [7:0]                cfg_ifg,
82	    input  wire                      cfg_tx_enable,
83	
84	    /*
85	     * Status
86	     */
87	    output wire [1:0]                start_packet,
88	    output wire                      error_underflow
89	);
90	
91	parameter EMPTY_WIDTH = $clog2(KEEP_WIDTH);
92	parameter MIN_LEN_WIDTH = $clog2(MIN_FRAME_LENGTH-4-CTRL_WIDTH+1);
93	
94	// bus width assertions
95	initial begin
96	    if (DATA_WIDTH != 64) begin
97	        $error("Error: Interface width must be 64");
98	        $finish;
99	    end
100	
101	    if (KEEP_WIDTH * 8 != DATA_WIDTH || CTRL_WIDTH * 8 != DATA_WIDTH) begin
102	        $error("Error: Interface requires byte (8-bit) granularity");
103	        $finish;
104	    end
105	end
106	
107	localparam [7:0]
108	    ETH_PRE = 8'h55,
109	    ETH_SFD = 8'hD5;
110	
111	localparam [7:0]
112	    XGMII_IDLE = 8'h07,
113	    XGMII_START = 8'hfb,
114	    XGMII_TERM = 8'hfd,
115	    XGMII_ERROR = 8'hfe;
116	
117	localparam [2:0]
118	    STATE_IDLE = 3'd0,
119	    STATE_PAYLOAD = 3'd1,
120	    STATE_PAD = 3'd2,
121	    STATE_FCS_1 = 3'd3,
122	    STATE_FCS_2 = 3'd4,
123	    STATE_ERR = 3'd5,
124	    STATE_IFG = 3'd6;
125	
126	reg [2:0] state_reg = STATE_IDLE, state_next;
127	
128	// datapath control signals
129	reg reset_crc;
130	reg update_crc;
131	
132	reg swap_lanes_reg = 1'b0, swap_lanes_next;
133	reg [31:0] swap_txd = 32'd0;
134	reg [3:0] swap_txc = 4'd0;
135	
136	reg [DATA_WIDTH-1:0] s_axis_tdata_masked;
137	
138	reg [DATA_WIDTH-1:0] s_tdata_reg = 0, s_tdata_next;
139	reg [EMPTY_WIDTH-1:0] s_empty_reg = 0, s_empty_next;
140	
141	reg [DATA_WIDTH-1:0] fcs_output_txd_0;
142	reg [DATA_WIDTH-1:0] fcs_output_txd_1;
143	reg [CTRL_WIDTH-1:0] fcs_output_txc_0;
144	reg [CTRL_WIDTH-1:0] fcs_output_txc_1;
145	
146	reg [7:0] ifg_offset;
147	
148	reg frame_start_reg = 1'b0, frame_start_next;
149	reg frame_reg = 1'b0, frame_next;
150	reg frame_error_reg = 1'b0, frame_error_next;
151	reg [MIN_LEN_WIDTH-1:0] frame_min_count_reg = 0, frame_min_count_next;
152	
153	reg [7:0] ifg_count_reg = 8'd0, ifg_count_next;
154	reg [1:0] deficit_idle_count_reg = 2'd0, deficit_idle_count_next;
155	
156	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
157	
158	reg [PTP_TS_WIDTH-1:0] m_axis_ptp_ts_reg = 0;
159	reg [PTP_TS_WIDTH-1:0] m_axis_ptp_ts_adj_reg = 0;
160	reg [PTP_TAG_WIDTH-1:0] m_axis_ptp_ts_tag_reg = 0;
161	reg m_axis_ptp_ts_valid_reg = 1'b0;
162	reg m_axis_ptp_ts_valid_int_reg = 1'b0;
163	reg m_axis_ptp_ts_borrow_reg = 1'b0;
164	
165	reg [31:0] crc_state_reg[7:0];
166	wire [31:0] crc_state_next[7:0];
167	
168	reg [4+16-1:0] last_ts_reg = 0;
169	reg [4+16-1:0] ts_inc_reg = 0;
170	
171	reg [DATA_WIDTH-1:0] xgmii_txd_reg = {CTRL_WIDTH{XGMII_IDLE}}, xgmii_txd_next;
172	reg [CTRL_WIDTH-1:0] xgmii_txc_reg = {CTRL_WIDTH{1'b1}}, xgmii_txc_next;
173	
174	reg start_packet_reg = 2'b00;
175	reg error_underflow_reg = 1'b0, error_underflow_next;
176	
177	assign s_axis_tready = s_axis_tready_reg;
178	
179	assign xgmii_txd = xgmii_txd_reg;
180	assign xgmii_txc = xgmii_txc_reg;
181	
182	assign m_axis_ptp_ts = PTP_TS_ENABLE ? ((!PTP_TS_FMT_TOD || m_axis_ptp_ts_borrow_reg) ? m_axis_ptp_ts_reg : m_axis_ptp_ts_adj_reg) : 0;
183	assign m_axis_ptp_ts_tag = PTP_TAG_ENABLE ? m_axis_ptp_ts_tag_reg : 0;
184	assign m_axis_ptp_ts_valid = PTP_TS_ENABLE || PTP_TAG_ENABLE ? m_axis_ptp_ts_valid_reg : 1'b0;
185	
186	assign start_packet = start_packet_reg;
187	assign error_underflow = error_underflow_reg;
188	
189	generate
190	    genvar n;
191	
192	    for (n = 0; n < 8; n = n + 1) begin : crc
193	        lfsr #(
194	            .LFSR_WIDTH(32),
195	            .LFSR_POLY(32'h4c11db7),
196	            .LFSR_CONFIG("GALOIS"),
197	            .LFSR_FEED_FORWARD(0),
198	            .REVERSE(1),
199	            .DATA_WIDTH(8*(n+1)),
200	            .STYLE("AUTO")
201	        )
202	        eth_crc (
203	            .data_in(s_tdata_reg[0 +: 8*(n+1)]),
204	            .state_in(crc_state_reg[7]),
205	            .data_out(),
206	            .state_out(crc_state_next[n])
207	        );
208	    end
209	
210	endgenerate
211	
212	function [2:0] keep2empty;
213	    input [7:0] k;
214	    casez (k)
215	        8'bzzzzzzz0: keep2empty = 3'd7;
216	        8'bzzzzzz01: keep2empty = 3'd7;
217	        8'bzzzzz011: keep2empty = 3'd6;
218	        8'bzzzz0111: keep2empty = 3'd5;
219	        8'bzzz01111: keep2empty = 3'd4;
220	        8'bzz011111: keep2empty = 3'd3;
221	        8'bz0111111: keep2empty = 3'd2;
222	        8'b01111111: keep2empty = 3'd1;
223	        8'b11111111: keep2empty = 3'd0;
224	    endcase
225	endfunction
226	
227	// Mask input data
228	integer j;
229	
230	always @* begin
231	    for (j = 0; j < 8; j = j + 1) begin
232	        s_axis_tdata_masked[j*8 +: 8] = s_axis_tkeep[j] ? s_axis_tdata[j*8 +: 8] : 8'd0;
233	    end
234	end
235	
236	// FCS cycle calculation
237	always @* begin
238	    casez (s_empty_reg)
239	        3'd7: begin
240	            fcs_output_txd_0 = {{2{XGMII_IDLE}}, XGMII_TERM, ~crc_state_next[0][31:0], s_tdata_reg[7:0]};
241	            fcs_output_txd_1 = {8{XGMII_IDLE}};
242	            fcs_output_txc_0 = 8'b11100000;
243	            fcs_output_txc_1 = 8'b11111111;
244	            ifg_offset = 8'd3;
245	        end
246	        3'd6: begin
247	            fcs_output_txd_0 = {XGMII_IDLE, XGMII_TERM, ~crc_state_next[1][31:0], s_tdata_reg[15:0]};
248	            fcs_output_txd_1 = {8{XGMII_IDLE}};
249	            fcs_output_txc_0 = 8'b11000000;
250	            fcs_output_txc_1 = 8'b11111111;
251	            ifg_offset = 8'd2;
252	        end
253	        3'd5: begin
254	            fcs_output_txd_0 = {XGMII_TERM, ~crc_state_next[2][31:0], s_tdata_reg[23:0]};
255	            fcs_output_txd_1 = {8{XGMII_IDLE}};
256	            fcs_output_txc_0 = 8'b10000000;
257	            fcs_output_txc_1 = 8'b11111111;
258	            ifg_offset = 8'd1;
259	        end
260	        3'd4: begin
261	            fcs_output_txd_0 = {~crc_state_next[3][31:0], s_tdata_reg[31:0]};
262	            fcs_output_txd_1 = {{7{XGMII_IDLE}}, XGMII_TERM};
263	            fcs_output_txc_0 = 8'b00000000;
264	            fcs_output_txc_1 = 8'b11111111;
265	            ifg_offset = 8'd8;
266	        end
267	        3'd3: begin
268	            fcs_output_txd_0 = {~crc_state_next[4][23:0], s_tdata_reg[39:0]};
269	            fcs_output_txd_1 = {{6{XGMII_IDLE}}, XGMII_TERM, ~crc_state_reg[4][31:24]};
270	            fcs_output_txc_0 = 8'b00000000;
271	            fcs_output_txc_1 = 8'b11111110;
272	            ifg_offset = 8'd7;
273	        end
274	        3'd2: begin
275	            fcs_output_txd_0 = {~crc_state_next[5][15:0], s_tdata_reg[47:0]};
276	            fcs_output_txd_1 = {{5{XGMII_IDLE}}, XGMII_TERM, ~crc_state_reg[5][31:16]};
277	            fcs_output_txc_0 = 8'b00000000;
278	            fcs_output_txc_1 = 8'b11111100;
279	            ifg_offset = 8'd6;
280	        end
281	        3'd1: begin
282	            fcs_output_txd_0 = {~crc_state_next[6][7:0], s_tdata_reg[55:0]};
283	            fcs_output_txd_1 = {{4{XGMII_IDLE}}, XGMII_TERM, ~crc_state_reg[6][31:8]};
284	            fcs_output_txc_0 = 8'b00000000;
285	            fcs_output_txc_1 = 8'b11111000;
286	            ifg_offset = 8'd5;
287	        end
288	        3'd0: begin
289	            fcs_output_txd_0 = s_tdata_reg;
290	            fcs_output_txd_1 = {{3{XGMII_IDLE}}, XGMII_TERM, ~crc_state_reg[7][31:0]};
291	            fcs_output_txc_0 = 8'b00000000;
292	            fcs_output_txc_1 = 8'b11110000;
293	            ifg_offset = 8'd4;
294	        end
295	    endcase
296	end
297	
298	always @* begin
299	    state_next = STATE_IDLE;
300	
301	    reset_crc = 1'b0;
302	    update_crc = 1'b0;
303	
304	    swap_lanes_next = swap_lanes_reg;
305	
306	    frame_start_next = 1'b0;
307	    frame_next = frame_reg;
308	    frame_error_next = frame_error_reg;
309	    frame_min_count_next = frame_min_count_reg;
310	
311	    ifg_count_next = ifg_count_reg;
312	    deficit_idle_count_next = deficit_idle_count_reg;
313	
314	    s_axis_tready_next = 1'b0;
315	
316	    s_tdata_next = s_tdata_reg;
317	    s_empty_next = s_empty_reg;
318	
319	    // XGMII idle
320	    xgmii_txd_next = {CTRL_WIDTH{XGMII_IDLE}};
321	    xgmii_txc_next = {CTRL_WIDTH{1'b1}};
322	
323	    error_underflow_next = 1'b0;
324	
325	    if (s_axis_tvalid && s_axis_tready) begin
326	        frame_next = !s_axis_tlast;
327	    end
328	
329	    case (state_reg)
330	        STATE_IDLE: begin
331	            // idle state - wait for data
332	            frame_error_next = 1'b0;
333	            frame_min_count_next = MIN_FRAME_LENGTH-4-CTRL_WIDTH;
334	            reset_crc = 1'b1;
335	            s_axis_tready_next = cfg_tx_enable;
336	
337	            // XGMII idle
338	            xgmii_txd_next = {CTRL_WIDTH{XGMII_IDLE}};
339	            xgmii_txc_next = {CTRL_WIDTH{1'b1}};
340	
341	            s_tdata_next = s_axis_tdata_masked;
342	            s_empty_next = keep2empty(s_axis_tkeep);
343	
344	            if (s_axis_tvalid && s_axis_tready) begin
345	                // XGMII start, preamble, and SFD
346	                xgmii_txd_next = {ETH_SFD, {6{ETH_PRE}}, XGMII_START};
347	                xgmii_txc_next = 8'b00000001;
348	                frame_start_next = 1'b1;
349	                s_axis_tready_next = 1'b1;
350	                state_next = STATE_PAYLOAD;
351	            end else begin
352	                swap_lanes_next = 1'b0;
353	                ifg_count_next = 8'd0;
354	                deficit_idle_count_next = 2'd0;
355	                state_next = STATE_IDLE;
356	            end
357	        end
358	        STATE_PAYLOAD: begin
359	            // transfer payload
360	            update_crc = 1'b1;
361	            s_axis_tready_next = 1'b1;
362	
363	            if (frame_min_count_reg > CTRL_WIDTH) begin
364	                frame_min_count_next = frame_min_count_reg - CTRL_WIDTH;
365	            end else begin
366	                frame_min_count_next = 0;
367	            end
368	
369	            xgmii_txd_next = s_tdata_reg;
370	            xgmii_txc_next = {CTRL_WIDTH{1'b0}};
371	
372	            s_tdata_next = s_axis_tdata_masked;
373	            s_empty_next = keep2empty(s_axis_tkeep);
374	
375	            if (!s_axis_tvalid || s_axis_tlast) begin
376	                s_axis_tready_next = frame_next; // drop frame
377	                frame_error_next = !s_axis_tvalid || s_axis_tuser[0];
378	                error_underflow_next = !s_axis_tvalid;
379	
380	                if (ENABLE_PADDING && frame_min_count_reg) begin
381	                    if (frame_min_count_reg > CTRL_WIDTH) begin
382	                        s_empty_next = 0;
383	                        state_next = STATE_PAD;
384	                    end else begin
385	                        if (keep2empty(s_axis_tkeep) > CTRL_WIDTH-frame_min_count_reg) begin
386	                            s_empty_next = CTRL_WIDTH-frame_min_count_reg;
387	                        end
388	                        if (frame_error_next) begin
389	                            state_next = STATE_ERR;
390	                        end else begin
391	                            state_next = STATE_FCS_1;
392	                        end
393	                    end
394	                end else begin
395	                    if (frame_error_next) begin
396	                        state_next = STATE_ERR;
397	                    end else begin
398	                        state_next = STATE_FCS_1;
399	                    end
400	                end
401	            end else begin
402	                state_next = STATE_PAYLOAD;
403	            end
404	        end
405	        STATE_PAD: begin
406	            // pad frame to MIN_FRAME_LENGTH
407	            s_axis_tready_next = frame_next; // drop frame
408	
409	            xgmii_txd_next = s_tdata_reg;
410	            xgmii_txc_next = {CTRL_WIDTH{1'b0}};
411	
412	            s_tdata_next = 64'd0;
413	            s_empty_next = 0;
414	
415	            update_crc = 1'b1;
416	
417	            if (frame_min_count_reg > CTRL_WIDTH) begin
418	                frame_min_count_next = frame_min_count_reg - CTRL_WIDTH;
419	                state_next = STATE_PAD;
420	            end else begin
421	                frame_min_count_next = 0;
422	                s_empty_next = CTRL_WIDTH-frame_min_count_reg;
423	                if (frame_error_reg) begin
424	                    state_next = STATE_ERR;
425	                end else begin
426	                    state_next = STATE_FCS_1;
427	                end
428	            end
429	        end
430	        STATE_FCS_1: begin
431	            // last cycle
432	            s_axis_tready_next = frame_next; // drop frame
433	
434	            xgmii_txd_next = fcs_output_txd_0;
435	            xgmii_txc_next = fcs_output_txc_0;
436	
437	            update_crc = 1'b1;
438	
439	            ifg_count_next = (cfg_ifg > 8'd12 ? cfg_ifg : 8'd12) - ifg_offset + (swap_lanes_reg ? 8'd4 : 8'd0) + deficit_idle_count_reg;
440	            if (s_empty_reg <= 4) begin
441	                state_next = STATE_FCS_2;
442	            end else begin
443	                state_next = STATE_IFG;
444	            end
445	        end
446	        STATE_FCS_2: begin
447	            // last cycle
448	            s_axis_tready_next = frame_next; // drop frame
449	
450	            xgmii_txd_next = fcs_output_txd_1;
451	            xgmii_txc_next = fcs_output_txc_1;
452	
453	            if (ENABLE_DIC) begin
454	                if (ifg_count_next > 8'd7) begin
455	                    state_next = STATE_IFG;
456	                end else begin
457	                    if (ifg_count_next >= 8'd4) begin
458	                        deficit_idle_count_next = ifg_count_next - 8'd4;
459	                        swap_lanes_next = 1'b1;
460	                    end else begin
461	                        deficit_idle_count_next = ifg_count_next;
462	                        ifg_count_next = 8'd0;
463	                        swap_lanes_next = 1'b0;
464	                    end
465	                    s_axis_tready_next = cfg_tx_enable;
466	                    state_next = STATE_IDLE;
467	                end
468	            end else begin
469	                if (ifg_count_next > 8'd4) begin
470	                    state_next = STATE_IFG;
471	                end else begin
472	                    s_axis_tready_next = cfg_tx_enable;
473	                    swap_lanes_next = ifg_count_next != 0;
474	                    state_next = STATE_IDLE;
475	                end
476	            end
477	        end
478	        STATE_ERR: begin
479	            // terminate packet with error
480	            s_axis_tready_next = frame_next; // drop frame
481	
482	            // XGMII error
483	            xgmii_txd_next = {XGMII_TERM, {7{XGMII_ERROR}}};
484	            xgmii_txc_next = {CTRL_WIDTH{1'b1}};
485	
486	            ifg_count_next = 8'd12;
487	
488	            state_next = STATE_IFG;
489	        end
490	        STATE_IFG: begin
491	            // send IFG
492	            s_axis_tready_next = frame_next; // drop frame
493	
494	            // XGMII idle
495	            xgmii_txd_next = {CTRL_WIDTH{XGMII_IDLE}};
496	            xgmii_txc_next = {CTRL_WIDTH{1'b1}};
497	
498	            if (ifg_count_reg > 8'd8) begin
499	                ifg_count_next = ifg_count_reg - 8'd8;
500	            end else begin
501	                ifg_count_next = 8'd0;
502	            end
503	
504	            if (ENABLE_DIC) begin
505	                if (ifg_count_next > 8'd7 || frame_reg) begin
506	                    state_next = STATE_IFG;
507	                end else begin
508	                    if (ifg_count_next >= 8'd4) begin
509	                        deficit_idle_count_next = ifg_count_next - 8'd4;
510	                        swap_lanes_next = 1'b1;
511	                    end else begin
512	                        deficit_idle_count_next = ifg_count_next;
513	                        ifg_count_next = 8'd0;
514	                        swap_lanes_next = 1'b0;
515	                    end
516	                    s_axis_tready_next = cfg_tx_enable;
517	                    state_next = STATE_IDLE;
518	                end
519	            end else begin
520	                if (ifg_count_next > 8'd4 || frame_reg) begin
521	                    state_next = STATE_IFG;
522	                end else begin
523	                    s_axis_tready_next = cfg_tx_enable;
524	                    swap_lanes_next = ifg_count_next != 0;
525	                    state_next = STATE_IDLE;
526	                end
527	            end
528	        end
529	    endcase
530	end
531	
532	always @(posedge clk) begin
533	    state_reg <= state_next;
534	
535	    swap_lanes_reg <= swap_lanes_next;
536	
537	    frame_start_reg <= frame_start_next;
538	    frame_reg <= frame_next;
539	    frame_error_reg <= frame_error_next;
540	    frame_min_count_reg <= frame_min_count_next;
541	
542	    ifg_count_reg <= ifg_count_next;
543	    deficit_idle_count_reg <= deficit_idle_count_next;
544	
545	    s_tdata_reg <= s_tdata_next;
546	    s_empty_reg <= s_empty_next;
547	
548	    s_axis_tready_reg <= s_axis_tready_next;
549	
550	    m_axis_ptp_ts_valid_reg <= 1'b0;
551	    m_axis_ptp_ts_valid_int_reg <= 1'b0;
552	
553	    start_packet_reg <= 2'b00;
554	    error_underflow_reg <= error_underflow_next;
555	
556	    if (PTP_TS_ENABLE && PTP_TS_FMT_TOD) begin
557	        m_axis_ptp_ts_valid_reg <= m_axis_ptp_ts_valid_int_reg;
558	        m_axis_ptp_ts_adj_reg[15:0] <= m_axis_ptp_ts_reg[15:0];
559	        {m_axis_ptp_ts_borrow_reg, m_axis_ptp_ts_adj_reg[45:16]} <= $signed({1'b0, m_axis_ptp_ts_reg[45:16]}) - $signed(31'd1000000000);
560	        m_axis_ptp_ts_adj_reg[47:46] <= 0;
561	        m_axis_ptp_ts_adj_reg[95:48] <= m_axis_ptp_ts_reg[95:48] + 1;
562	    end
563	
564	    if (frame_start_reg) begin
565	        if (swap_lanes_reg) begin
566	            if (PTP_TS_ENABLE) begin
567	                if (PTP_TS_FMT_TOD) begin
568	                    m_axis_ptp_ts_reg[45:0] <= ptp_ts[45:0] + (ts_inc_reg >> 1);
569	                    m_axis_ptp_ts_reg[95:48] <= ptp_ts[95:48];
570	                end else begin
571	                    m_axis_ptp_ts_reg <= ptp_ts + (ts_inc_reg >> 1);
572	                end
573	            end
574	            start_packet_reg <= 2'b10;
575	        end else begin
576	            if (PTP_TS_ENABLE) begin
577	                m_axis_ptp_ts_reg <= ptp_ts;
578	            end
579	            start_packet_reg <= 2'b01;
580	        end
581	        if (PTP_TS_ENABLE) begin
582	            if (PTP_TS_CTRL_IN_TUSER) begin
583	                m_axis_ptp_ts_tag_reg <= s_axis_tuser >> 2;
584	                if (PTP_TS_FMT_TOD) begin
585	                    m_axis_ptp_ts_valid_int_reg <= s_axis_tuser[1];
586	                end else begin
587	                    m_axis_ptp_ts_valid_reg <= s_axis_tuser[1];
588	                end
589	            end else begin
590	                m_axis_ptp_ts_tag_reg <= s_axis_tuser >> 1;
591	                if (PTP_TS_FMT_TOD) begin
592	                    m_axis_ptp_ts_valid_int_reg <= 1'b1;
593	                end else begin
594	                    m_axis_ptp_ts_valid_reg <= 1'b1;
595	                end
596	            end
597	        end
598	    end
599	
600	    crc_state_reg[0] <= crc_state_next[0];
601	    crc_state_reg[1] <= crc_state_next[1];
602	    crc_state_reg[2] <= crc_state_next[2];
603	    crc_state_reg[3] <= crc_state_next[3];
604	    crc_state_reg[4] <= crc_state_next[4];
605	    crc_state_reg[5] <= crc_state_next[5];
606	    crc_state_reg[6] <= crc_state_next[6];
607	
608	    if (update_crc) begin
609	        crc_state_reg[7] <= crc_state_next[7];
610	    end
611	
612	    if (reset_crc) begin
613	        crc_state_reg[7] <= 32'hFFFFFFFF;
614	    end
615	
616	    swap_txd <= xgmii_txd_next[63:32];
617	    swap_txc <= xgmii_txc_next[7:4];
618	
619	    if (swap_lanes_reg) begin
620	        xgmii_txd_reg <= {xgmii_txd_next[31:0], swap_txd};
621	        xgmii_txc_reg <= {xgmii_txc_next[3:0], swap_txc};
622	    end else begin
623	        xgmii_txd_reg <= xgmii_txd_next;
624	        xgmii_txc_reg <= xgmii_txc_next;
625	    end
626	
627	    last_ts_reg <= ptp_ts;
628	    ts_inc_reg <= ptp_ts - last_ts_reg;
629	
630	    if (rst) begin
631	        state_reg <= STATE_IDLE;
632	
633	        frame_start_reg <= 1'b0;
634	        frame_reg <= 1'b0;
635	
636	        swap_lanes_reg <= 1'b0;
637	
638	        ifg_count_reg <= 8'd0;
639	        deficit_idle_count_reg <= 2'd0;
640	
641	        s_axis_tready_reg <= 1'b0;
642	
643	        m_axis_ptp_ts_valid_reg <= 1'b0;
644	        m_axis_ptp_ts_valid_int_reg <= 1'b0;
645	
646	        xgmii_txd_reg <= {CTRL_WIDTH{XGMII_IDLE}};
647	        xgmii_txc_reg <= {CTRL_WIDTH{1'b1}};
648	
649	        start_packet_reg <= 2'b00;
650	        error_underflow_reg <= 1'b0;
651	    end
652	end
653	
654	endmodule
655	
656	`resetall
